use super::*;
use orr_sample::{project_create::{create,CreateOptions},room_project::PreparedProject};
use std::collections::BTreeMap;
pub(crate) struct Fixture {pub temp:tempfile::TempDir,pub root:PathBuf}
pub(crate) fn fixture(character:bool,lighting:bool)->Fixture {
    let temp=tempfile::tempdir().unwrap();let root=temp.path().canonicalize().unwrap().join("presentation Room");let generated_character=character && cfg!(feature="room-character");create(&CreateOptions {output:root.clone(),template:(if generated_character {"room-escape-character-3d-v1"}else{"room-escape-3d-v1"}).into(),seed:"package-presentation".into()}).unwrap();
    let manifest=root.join("orr.project.json");let mut json:serde_json::Value=serde_json::from_slice(&fs::read(&manifest).unwrap()).unwrap();
    if character && !generated_character {let p=PreparedProject::open(&root).unwrap();let entity=p.scene().frame().entities().find(|&e|p.scene().frame().get::<orr_sample::room_game::RoomActor>(e).is_some_and(|a|a.kind==orr_sample::room_game::PLAYER)).unwrap();let guid=p.scene().index().guid(entity).unwrap().to_string();json["entry"]["character"]=serde_json::json!("room.character.json");fs::write(root.join("room.character.json"),serde_json::to_vec(&serde_json::json!({"schema":1,"player":guid,"searching":0,"carrying":1,"escaped":2})).unwrap()).unwrap();}
    if lighting {json["entry"]["lighting"]=serde_json::json!("room.lighting.json");fs::write(root.join("room.lighting.json"),br#"{"version":3,"point_light":{"position":[0,4,0],"color":[1,0.9,0.7],"intensity":3,"range":12},"follow_player":[1,2,-1],"activation":"key_collected"}"#).unwrap();}
    fs::write(manifest,serde_json::to_vec_pretty(&json).unwrap()).unwrap();Fixture {temp,root}
}
fn source(f:&Fixture,version:&str)->PathBuf {let path=f.temp.path().join(format!("extra-{version}"));fs::create_dir(&path).unwrap();fs::write(path.join("orr.package.json"),serde_json::to_vec(&serde_json::json!({"schema":1,"name":"extra","version":version,"engine":"^0.0.1","capabilities":[],"dependencies":{},"files":["asset.txt","LICENSE.txt"]})).unwrap()).unwrap();fs::write(path.join("asset.txt"),version).unwrap();fs::write(path.join("LICENSE.txt"),"User fixture license").unwrap();path}
fn files(root:&Path)->BTreeMap<PathBuf,Vec<u8>> {fn walk(root:&Path,path:&Path,out:&mut BTreeMap<PathBuf,Vec<u8>>) {for e in fs::read_dir(path).unwrap() {let e=e.unwrap();let p=e.path();if e.file_type().unwrap().is_dir() {walk(root,&p,out);}else{out.insert(p.strip_prefix(root).unwrap().to_path_buf(),fs::read(p).unwrap());}}}let mut out=BTreeMap::new();walk(root,root,&mut out);out}
#[test]
fn room_presentation_admission_requires_this_editors_explicit_flags() {
    for (character,lighting) in [(false,false),(true,false),(false,true),(true,true)] {let f=fixture(character,lighting);let before=files(&f.root);let result=inspect(&f.root);let expected=(!character || cfg!(feature="room-character")) && (!lighting || cfg!(feature="room-lighting"));assert_eq!(result.is_ok(),expected,"character={character} lighting={lighting}: {:?}",result.err());assert_eq!(files(&f.root),before);
        if !expected {let error=open_room_project(&f.root).err().unwrap();assert!(error.contains("explicit") && error.contains("consumer support"),"{error}");}
    }
}
#[test]
fn unified_sample_animation_does_not_expand_editor_inventory() {
    let f=fixture(false,false);let path=source(&f,"1.0.0");let manifest=path.join("orr.package.json");let mut json:serde_json::Value=serde_json::from_slice(&fs::read(&manifest).unwrap()).unwrap();json["capabilities"]=serde_json::json!(["animation"]);fs::write(manifest,serde_json::to_vec(&json).unwrap()).unwrap();Project::open_for_install(&f.root,Runtime::content_only().engine_version).unwrap().install(&[path]).unwrap();let before=files(&f.root);assert_eq!(inspect(&f.root).is_ok(),cfg!(feature="room-animated-models"));assert_eq!(files(&f.root),before);
}
#[cfg(all(feature="room-character",feature="room-lighting"))]
fn edit_profile(f:&Fixture,field:&str,second:bool) {let path=f.root.join(format!("room.{field}.json"));let mut value:serde_json::Value=serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();if field=="lighting" {value["point_light"]["intensity"]=serde_json::json!(if second {5.0}else{4.0});}else{value["schema"]=serde_json::json!(2);value["speeds"]=serde_json::json!({"searching":if second {"4x"}else{"2x"},"carrying":"1x","escaped":"1x"});}fs::write(path,serde_json::to_vec_pretty(&value).unwrap()).unwrap();open_room_project(&f.root).unwrap();}
#[cfg(all(feature="room-character",feature="room-lighting"))]
#[test]
fn stale_valid_character_or_lighting_edits_invalidate_remove_update_impact_and_restore() {
    for field in ["lighting","character"] {let f=fixture(true,true);let added=apply_add(&plan_add(&f.root,&source(&f,"1.0.0")).unwrap()).unwrap();let next=source(&f,"2.0.0");let remove=plan_remove(&f.root,"extra").unwrap();let update=plan_update(&f.root,&next).unwrap();let impact=inspect_update_impact(&f.root,&next).unwrap();edit_profile(&f,field,false);let before=files(&f.root);assert!(apply_remove(&remove).is_err());assert!(apply_update(&update).is_err());assert!(impact.validate_current().is_err());assert_eq!(inspect(&f.root).unwrap(),added);assert_eq!(files(&f.root),before);
        let (removed,receipt)=apply_remove_with_receipt(&plan_remove(&f.root,"extra").unwrap()).unwrap();edit_profile(&f,field,true);let before=files(&f.root);assert!(plan_restore(&receipt).is_err());assert!(apply_restore(receipt).is_err());assert_eq!(inspect(&f.root).unwrap(),removed);assert_eq!(files(&f.root),before);
    }
}
#[cfg(all(feature="room-character",feature="room-lighting",feature="windows-export"))]
#[test]
#[ignore="explicit compiled presentation-capable runtime required"]
fn saved_character_and_light_survive_package_lifecycle_and_source_hidden_native_export() {
    use sha2::{Digest,Sha256};use std::process::Command;
    let f=fixture(true,true);let original=files(&f.root);let prepared=open_room_project(&f.root).unwrap();let initial=prepared.scene().frame().to_bytes();let light=prepared.lighting().unwrap().document.clone();let character=prepared.character().unwrap().document.clone();let added=apply_add(&plan_add(&f.root,&source(&f,"1.0.0")).unwrap()).unwrap();assert!(added.direct.contains_key("extra"));let updated=apply_update(&plan_update(&f.root,&source(&f,"2.0.0")).unwrap()).unwrap();let (_,receipt)=apply_remove_with_receipt(&plan_remove(&f.root,"extra").unwrap()).unwrap();plan_restore(&receipt).unwrap();assert_eq!(apply_restore(receipt).unwrap(),updated);
    let prepared=open_room_project(&f.root).unwrap();assert_eq!(prepared.scene().frame().to_bytes(),initial);assert_eq!(prepared.lighting().unwrap().document,light);assert_eq!(prepared.character().unwrap().document,character);let after=files(&f.root);for name in ["orr.project.json","room.scene.yaml","room.models.json","room.camera.json","room.character.json","room.lighting.json"] {assert_eq!(after[Path::new(name)],original[Path::new(name)]);}
    let mut sim=prepared.scene().simulation().unwrap();for _ in 0..8 {let mut input=orr_sim::TickInputs::new(sim.tick()+1,1);input.set_input(orr_sim::PlayerSlot(0),orr_sample::room_game::RoomInput {move_x:1,buttons:orr_sample::room_game::INTERACT,..Default::default()});sim.step(&input);}assert_eq!(sim.frame().singleton::<orr_sample::room_game::RoomRun>().key_collected,1);let expected=format!("room tick: 8 checksum: 0x{:016x}",sim.frame().checksum());
    let built=PathBuf::from(std::env::var_os("ORR_PRESENTATION_PACKAGE_RUNTIME").expect("explicit built runtime"));let runtime=f.temp.path().join("trusted profile runtime");fs::copy(built,&runtime).unwrap();let hash:String=Sha256::digest(fs::read(&runtime).unwrap()).iter().map(|b|format!("{b:02x}")).collect();let bundle=f.temp.path().join("profile package game");orr_sample::project_export::export_room(&orr_sample::project_export::ExportOptions {project:f.root.clone(),runtime:runtime.clone(),runtime_sha256:hash,output:bundle.clone(),trusted_runtime:true,source_revision:None}).unwrap();fs::rename(&f.root,f.root.with_extension("hidden")).unwrap();fs::rename(&runtime,runtime.with_extension("hidden")).unwrap();let output=Command::new(bundle.join("run-room-escape")).current_dir(f.temp.path()).args(["--headless","--ticks","8","--hold","right,interact","--check-model-poses"]).env_remove("DISPLAY").env_remove("WAYLAND_DISPLAY").output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));let text=String::from_utf8(output.stdout).unwrap();assert!(text.contains(&expected));assert!(text.contains("room model poses: 9 frames checked;"));assert!(text.contains("room lighting active: 1"));
}
